/// Bit *i* is set when `PATHS[i]` is an object node rather than a translation.
/// A branch is a distinct lookup outcome, not a miss: `t("home")` must return the
/// byte-exact diagnostic `key 'home (en)' returned an object instead of string.`,
/// which a flat map could never distinguish from an absent key.
pub(crate) static IS_BRANCH: [u8; 204] = [
    0x01, 0x00, 0x10, 0x80, 0x00, 0x00, 0x00, 0x00, 0x00, 0x01, 0x00, 0x00, 0x08, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x80, 0x80, 0x01, 0x00, 0x40, 0x00, 0x00, 0x00, 0x18, 0x00,
    0x00, 0x00, 0x85, 0x44, 0x00, 0x00, 0x00, 0x40, 0x00, 0x80, 0x40, 0x08, 0x28, 0x00, 0x00, 0x01,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0x40, 0x00, 0x06, 0x00, 0x00, 0x00, 0x01, 0x00, 0x00,
    0x00, 0x08, 0x04, 0x00, 0x00, 0x00, 0x08, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x80, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x40, 0x00, 0x00, 0x08, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x40, 0x80, 0x01, 0x00, 0x00, 0x00, 0x00, 0x40, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x20, 0x80, 0x00, 0x00, 0x00, 0x20, 0x00, 0x04, 0x00, 0xc0,
    0x49, 0x92, 0x84, 0x00, 0x10, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0x00, 0x01, 0x00, 0x01, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x20, 0x08, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0xc0, 0x24, 0x40, 0x80, 0x10, 0x20, 0x21, 0x02, 0x04, 0x82, 0x80, 0x00, 0x00, 0x00, 0x30, 0x04,
    0x00, 0x00, 0x10, 0x00, 0x22, 0x00, 0x01, 0x08, 0x04, 0x10, 0x04, 0x00,
];

/// Number of entries in [`PATHS`]. Value tables carry `N_PATHS + 1` offsets.
pub(crate) const N_PATHS: usize = 1628;

/// Index of `path` in [`PATHS`], or `None`.
pub(crate) fn path_id(path: &str) -> Option<usize> {
    PATHS.binary_search(&path).ok()
}

/// Whether `PATHS[id]` is an object node.
pub(crate) fn is_branch(id: usize) -> bool {
    IS_BRANCH[id >> 3] & (1 << (id & 7)) != 0
}
